async function taskBackup(conn: Client, a: { id: string; username: string }, tsLabel: string): Promise<void> {
  const u = a.username;
  const dir = `/var/hosting-backups/${u}`;
  const dumpDir = `${dir}/dbdump`;
  const path = `${dir}/${tsLabel}.tar.gz`;
  // Root-only staging for the DB dumps; the whole dir is 700 root:root so the
  // tenant can neither read nor tamper with it.
  await run(
    conn,
    "dump dbs",
    `rm -rf ${dumpDir}; mkdir -p ${dumpDir}; chown -R root:root ${dir}; chmod 700 ${dir} ${dumpDir}; ` +
      `for dbn in $(mysql -N -e "SHOW DATABASES LIKE '${u}\\_%'" 2>/dev/null); do mysqldump "$dbn" > ${dumpDir}/"$dbn".sql 2>/dev/null; done`,
  );
  // One archive holding the home tree (${u}/…) and the root-owned dumps (dbdump/…).
  await run(conn, "tar home", `tar -czf ${path} -C /home ${u} -C ${dir} dbdump && rm -rf ${dumpDir}`);
  const st = await exec(conn, `stat -c %s ${path} 2>/dev/null || echo 0`);
  const sizeBytes = Math.max(0, Math.min(2_000_000_000, Number(st.out.trim()) || 0));
  await db.hostingBackup.create({ data: { accountId: a.id, path, sizeBytes } });
  // Retain the newest 5 per account; delete older files + rows.
  const all = await db.hostingBackup.findMany({ where: { accountId: a.id }, orderBy: { createdAt: "desc" } });
  for (const old of all.slice(5)) {
    await exec(conn, `rm -f ${old.path}`).catch(() => undefined);
    await db.hostingBackup.delete({ where: { id: old.id } }).catch(() => undefined);
  }
}

